    // B[i][j] = (DATA_TYPE)((n + i - j) % 100) / m;
    //
    // With our Buffer layout C(j, i), B(j, i):
    Func init_C("init_C"), init_B("init_B");

    Expr m_inv = cast<num_t>(1.0f) / cast<num_t>(m);

    init_C(j, i) = cast<num_t>(((i + j) % 100)) * m_inv;
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) * m_inv;

    // Initialize A:
    //
    // for (i = 0; i < m; i++) {
    //   for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //       A[i][j] = -999;
    // }
    //
    // We store A[i][j] at A(j, i), and fill the "unused" upper part with -999.
    Func init_A("init_A");
    Expr lower_tri = cast<num_t>(((i + j) % 100)) * m_inv;
    Expr unused    = cast<num_t>(-999);
    init_A(j, i)   = select(j <= i, lower_tri, unused);

    // Simple CPU-oriented schedules for the initializers. They are not
    // performance-critical, but we still give them reasonable locality.
    const int vec = 8;  // reasonable default for modern x86 (8 floats / 4 doubles)

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec);

    // Realize into the provided buffers
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from symm.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C, B : MxN  -> (n, m) in Halide
    //   A    : MxM  -> (m, m) in Halide
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Vars and reduction domain
    Var i("i"), j("j");
    // A is MxM stored as A(j, i); its logical size in the "row" dimension is m.
    RDom k(0, m, "k");

    // Main computational kernel in Halide.
    //
    // Original BLAS semantics:
    //   C := alpha * A * B + beta * C
    // with A symmetric, stored in its lower triangular part.
    //
    // We construct a symmetric view of A:
    //   A_sym(i, l) =
    //      (l <= i) ? A(i, l)  : A(l, i)
    //
    // Remember our Buffer mapping:
    //   original A[i][l] -> A_param(l, i)
    //   original A[l][i] -> A_param(i, l)
    //
    // So we define:
    //   A_sym(i, k) = (k <= i) ? A_param(k, i) : A_param(i, k)
    //
    // Then:
    //   symm(j, i) = beta * C_param(j, i)
    //   symm(j, i) += alpha * sum_k A_sym(i, k) * B_param(j, k)
    //
    Func symm("symm");

    Expr beta_expr  = cast<num_t>(beta);
    Expr alpha_expr = cast<num_t>(alpha);

    // Base: beta * C
    symm(j, i) = beta_expr * C_param(j, i);

    // Symmetric access to A
    Expr A_sym = select(k <= i, A_param(k, i), A_param(i, k));

    // Accumulate alpha * A_sym * B
    symm(j, i) += alpha_expr * A_sym * B_param(j, k);

    // ---------------------------------------------------------------------
    // Optimized schedule for symm
    //
    // Goals:
    //   - Good data locality in A, B, and C.
    //   - Exploit vector units along the contiguous j-dimension.
    //   - Use multi-core parallelism across 2D tiles of (i, j).
    //
    // Strategy:
    //   * Tile the (j, i) space into 2D tiles.
    //   * Fuse the tile indices to get a single parallel loop over tiles.
    //   * Vectorize along the innermost j coordinate inside each tile.
    //   * Apply a similar reordering to the update step so the reduction
    //     over k is inside each tile and outside the innermost j loop.
    // ---------------------------------------------------------------------
    Var jo("jo"), ji("ji"), io("io"), ii("ii"), tile_index("tile_index");

    const int tile_j = 64;  // tile size along N (j) dimension
    const int tile_i = 64;  // tile size along M (i) dimension
    const int vec    = 8;   // vector width along j (tuned for modern x86)

    // Pure definition: tile output space, fuse tiles, then parallelize and vectorize.
    symm
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Fuse jo and io so that we can parallelize across 2D tiles
        // without nested parallel loops.
        .fuse(jo, io, tile_index)
        // Make ji the innermost loop for contiguous access in j.
        .reorder(ji, ii, tile_index)
        .vectorize(ji, vec)
        .parallel(tile_index);

    // Update definition (the reduction over k):
    // We want the same tile structure, but now also include the reduction
    // loop k inside each tile, while still vectorizing across ji.
    symm.update()
        .reorder(ji, ii, k, tile_index)
        .vectorize(ji, vec)
        .parallel(tile_index);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel
    symm.compile_jit();

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    //
    // Note: C is used as both input (through C_param) and output here.
    // The pure definition stage reads C_param(j,i) once per element to
    // compute beta * C, then the update stage no longer references C_param.
    // This matches the BLAS semantics C := beta*C + alpha*A*B.
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii, jj) in C layout is C(jj, ii) in our Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
