#include "symm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization, translated from the original C version.
 *
 * Original C signature:
 *   void init_array(int m, int n,
 *                   DATA_TYPE *alpha,
 *                   DATA_TYPE *beta,
 *                   DATA_TYPE C[M][N],
 *                   DATA_TYPE A[M][M],
 *                   DATA_TYPE B[M][N]);
 *
 * Mapping:
 *   - C[i][j] (MxN) -> Buffer C(j, i) with shape (n, m)
 *   - B[i][j] (MxN) -> Buffer B(j, i) with shape (n, m)
 *   - A[i][j] (MxM) -> Buffer A(j, i) with shape (m, m)
 */
static
void init_array(int m, int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Initialize C and B:
    //
    // C[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    // B[i][j] = (DATA_TYPE)((n + i - j) % 100) / m;
    //
    // With our Buffer layout C(j, i), B(j, i):
    Func init_C("init_C"), init_B("init_B");

    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // Initialize A:
    //
    // for (i = 0; i < m; i++) {
    //   for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //       A[i][j] = -999;
    // }
    //
    // We store A[i][j] at A(j, i), and fill the "unused" upper part with -999.
    Func init_A("init_A");
    Expr lower_tri = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    Expr unused    = cast<num_t>(-999);
    init_A(j, i)   = select(j <= i, lower_tri, unused);

    // Realize into the provided buffers
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from symm.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C, B : MxN  -> (n, m) in Halide
    //   A    : MxM  -> (m, m) in Halide
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Vars and reduction domain
    Var i("i"), j("j");
    // A is MxM stored as A(j, i); extent of dim(0) is m
    RDom k(0, A.dim(0).extent(), "k");

    // Target information (used for picking good vector widths)
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // --- Main computational kernel in Halide. --------------------------------
    //
    // Original BLAS semantics:
    //   C := alpha * A * B + beta * C
    // with A symmetric, stored in its lower triangular part.
    //
    // We first materialize a symmetric view of A into an auxiliary Func
    // to avoid re-doing the triangular address computation for every (j,k)
    // and to avoid a 'select' in the innermost loop:
    //
    //   A_sym_full(k, i) =
    //      (k <= i) ? A(i, k)  : A(k, i)
    //
    // In terms of ImageParam indexing and our Buffer mapping:
    //   original A[i][l] -> A_param(l, i)
    //   original A[l][i] -> A_param(i, l)
    //
    // so:
    //   A_sym_full(k, i) = (k <= i) ? A_param(k, i) : A_param(i, k)
    //
    // Once this is precomputed (O(m^2)), we reuse it across all columns j,
    // which reduces address arithmetic and branching in the O(m^2 n) kernel.
    Var kk("kk"), ii("ii");
    Func A_sym_full("A_sym_full");
    A_sym_full(kk, ii) = select(kk <= ii,
                                A_param(kk, ii),
                                A_param(ii, kk));

    // Main SYMM kernel:
    //
    // Using our Buffer mapping:
    //   original C[i][j] -> C_param(j, i)
    //   original B[i][j] -> B_param(j, i)
    //
    // We compute:
    //   symm(j, i) = beta * C_param(j, i)
    //   symm(j, i) += alpha * sum_k A_sym_full(k, i) * B_param(j, k)
    //
    // Note: C_param and the output buffer C alias in memory. This is safe
    // because each element of C is read once (for beta*C) before being
    // overwritten with the final result.
    Func symm("symm");

    // Base: beta * C
    symm(j, i) = Expr(beta) * C_param(j, i);

    // Accumulate alpha * A_sym_full * B
    symm(j, i) += Expr(alpha) * A_sym_full(k, i) * B_param(j, k);

    // ------------------------ Scheduling -------------------------------------
    //
    // 1) Precompute the symmetric view of A:
    //    - This is O(m^2) and independent of j, so we compute it once.
    //    - Parallelize across rows of A (ii) and vectorize across columns (kk).
    A_sym_full
        .compute_root()
        .parallel(ii)
        .vectorize(kk, vec_width);

    // 2) Schedule the main SYMM kernel.
    //
    // symm(j, i) is realized into C(j, i) with shape (n, m).
    // We want:
    //   - j (columns) contiguous in memory and vectorized.
    //   - i (rows) distributed across threads.
    //   - the reduction over k in the middle: for each (i,k) we walk
    //     B(j,k) contiguously in j.
    //
    // Pure definition: symm(j, i) = beta * C(j, i)
    symm
        .compute_root()
        // Parallelize across rows (i) to use all cores.
        .parallel(i)
        // Vectorize across contiguous columns of C / B.
        .vectorize(j, vec_width);

    // Update definition: symm(j, i) += ...
    symm.update()
        // Make j innermost, then k, then i outermost:
        //   for i:
        //     for k:
        //       for j (vectorized):
        //         symm(j,i) += ...
        .reorder(j, k, i)
        .parallel(i)
